INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:cursor:config-model-v1','project_doc','seed://cursor/config-model','Cursor command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: ~/.cursor/mcp.json, .cursor/rules/, .cursorrules; MCP servers under mcpServers. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: docs/UNIVERSAL_COMMAND_MATRIX.md and docs/COMPATIBILITY_MATRIX.md.','docs/UNIVERSAL_COMMAND_MATRIX.md and docs/COMPATIBILITY_MATRIX.md','faa86a4c88406404a9c6b2ef75ce7dbd15b5b90bfceab8ed78956f9f1724f02f','cursor,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:cursor:integration-points-v1','project_doc','seed://cursor/integration','Cursor command surface Simplicio integration points','Snapshot date: 2026-07-15. T2 MCP plus rules; preserve existing project rules and server entries. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: docs/UNIVERSAL_COMMAND_MATRIX.md and docs/COMPATIBILITY_MATRIX.md.','docs/UNIVERSAL_COMMAND_MATRIX.md and docs/COMPATIBILITY_MATRIX.md','6691c79ec30d56b521a45dc639bc2307b5184b193abbc7b7e38883b9bdd41cc9','cursor,simplicio,integration,governance',2);
